orchard.stored(async ({ binId, variety, storageWeeks }) => {
  const { perBushel } = await orchard.getPrice({ variety })
  const targetPrice = getTargetPrice(variety)

  if (perBushel >= targetPrice || storageWeeks >= 30) {
    await orchard.pack({
      binId,
      grades: ['ExtraFancy', 'Fancy'],
      sizes: ['80', '88', '100']
    })
  }
