  if (grade === 'ExtraFancy' && size === '80') {
    await orchard.sell({
      lotId,
      market: 'export',
      destination: 'asia'
    })
  } else if (grade === 'Fancy') {
    await orchard.sell({
      lotId,
      market: 'domestic-retail'
    })
  } else {
    await orchard.sell({
      lotId,
      market: 'processor'
    })
