  quoteId: quote.id,
  carrierId: quote.options[0].carrierId,
  shipper: { name: 'China Auto Parts', contact: 'export@cap.cn' },
  consignee: { name: 'US Auto Assembly', contact: 'import@usaa.com' }
})

// Track shipment in transit
